		} else {
			var changePercentage = tw.local.odcRequest.ChargesAndCommissions[i].changePercentage;
			if (changePercentage < 0 || changePercentage == null || changePercentage == undefined) {
				addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].changePercentage", "Change Percentage Must be >= 0", "Change Percentage Must be >= 0");
			}

			if (changePercentage > 0 && changePercentage > 100) {
				addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].changePercentage", "Change Percentage Must be <= 100", "Change Percentage Must be <= 100");
			}
		}

		//skip validation if waiver or changeAmnt < 0
		if (tw.local.odcRequest.ChargesAndCommissions[i].waiver == false && tw.local.odcRequest.ChargesAndCommissions[i].changeAmount > 0) {
			//GL Account
			if (tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.accountClass.value == "GL Account") {
				if (tw.local.odcRequest.ChargesAndCommissions[i].isGLFound == false) {
					addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.glAccountNo", "GL Account Not Verified", "GL Account Not Verified");
				}

				mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.glAccountNo, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.glAccountNo");
				mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.currency.value, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.currency");
				mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.branchCode, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.branchCode");

				//Customer Account
			} else {
				mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.customerAccountNo, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.customerAccountNo");
			}

			//DebitedAmount

			if (tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate > 0) {
				validateDecimal(tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAmount.negotiatedExRate", "This field accepts 14 digits before the decimal point and 2 digits after it.");
			}

			//Correct Validation but Waiting confirmation on what to do if GL account
			if (tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.amountInAccount > tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.balance && tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.isOverDraft == false) {
				addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAmount.amountInAccount", "ERROR: Debited Amount in account currency Must be <= Account Balance", "ERROR: Debited Amount in account currency Must be <= Account Balance");
			}
		}
	}
	validateTab(9, "Charges and commisions Tab");
	//----------------------------------------------- Parties VALIDATION -------------------------------------
	var cifList = [];
	/////Drawer Section
	var drawerCif = tw.local.odcRequest.Parties.Drawer.partyId;
	addIfNotPresent(cifList, drawerCif);
	mandatory(tw.local.odcRequest.Parties.Drawer.partyId, "tw.local.odcRequest.Parties.Drawer.partyId");
	mandatory(tw.local.odcRequest.Parties.Drawer.partyName, "tw.local.odcRequest.Parties.Drawer.partyName");
	mandatory(tw.local.odcRequest.Parties.Drawer.country, "tw.local.odcRequest.Parties.Drawer.country");
	mandatory(tw.local.odcRequest.Parties.Drawer.Language, "tw.local.odcRequest.Parties.Drawer.Language");
	mandatory(tw.local.odcRequest.Parties.Drawer.Reference, "tw.local.odcRequest.Parties.Drawer.Reference");
	mandatory(tw.local.odcRequest.Parties.Drawer.address1, "tw.local.odcRequest.Parties.Drawer.address1");

	/////Drawee Section
	var draweeCif = tw.local.odcRequest.Parties.Drawee.partyId;
	if (draweeCif && addIfNotPresent(cifList, draweeCif) == false) {
		addError("tw.local.odcRequest.Parties.Drawee.partyId", "Please Make sure that each CIF is different for each Party", "Please Make sure that each CIF is different for each Party");
	}
	mandatory(tw.local.odcRequest.Parties.Drawee.partyId, "tw.local.odcRequest.Parties.Drawee.partyId");
	mandatory(tw.local.odcRequest.Parties.Drawee.partyName, "tw.local.odcRequest.Parties.Drawee.partyName");
	mandatory(tw.local.odcRequest.Parties.Drawee.country, "tw.local.odcRequest.Parties.Drawee.country");
	mandatory(tw.local.odcRequest.Parties.Drawee.Language, "tw.local.odcRequest.Parties.Drawee.Language");
	mandatory(tw.local.odcRequest.Parties.Drawee.Reference, "tw.local.odcRequest.Parties.Drawee.Reference");
	mandatory(tw.local.odcRequest.Parties.Drawee.address1, "tw.local.odcRequest.Parties.Drawee.address1");

	//////Collecting bank(optional)
	var collectingBankCif = tw.local.odcRequest.Parties.collectingBank.cif;
	mandatory(collectingBankCif, "tw.local.odcRequest.Parties.collectingBank.cif");
	var collectingBankId = tw.local.odcRequest.Parties.collectingBank.id;
	if (collectingBankCif && collectingBankCif.length < 8) {
		addError("tw.local.odcRequest.Parties.collectingBank.cif", "Please enter a Valid CIF or totally remove it", "Please enter a Valid CIF or totally remove it");
	} else if (collectingBankCif && !collectingBankId) {
		addError("tw.local.odcRequest.Parties.collectingBank.cif", "Please Retrieve CIF Information", "Please Retrieve CIF Information");
	} else if (collectingBankCif) {
		if (addIfNotPresent(cifList, collectingBankCif) == false) {
			addError("tw.local.odcRequest.Parties.collectingBank.cif", "Please Make sure that each CIF is different for each Party", "Please Make sure that each CIF is different for each Party");
		}
		mandatory(tw.local.odcRequest.Parties.collectingBank.id, "tw.local.odcRequest.Parties.collectingBank.id");
		mandatory(tw.local.odcRequest.Parties.collectingBank.name, "tw.local.odcRequest.Parties.collectingBank.name");
		mandatory(tw.local.odcRequest.Parties.collectingBank.country, "tw.local.odcRequest.Parties.collectingBank.country");
		mandatory(tw.local.odcRequest.Parties.collectingBank.language, "tw.local.odcRequest.Parties.collectingBank.language");
		mandatory(tw.local.odcRequest.Parties.collectingBank.reference, "tw.local.odcRequest.Parties.collectingBank.reference");
		mandatory(tw.local.odcRequest.Parties.collectingBank.address1, "tw.local.odcRequest.Parties.collectingBank.address1");
		mandatory(tw.local.odcRequest.Parties.collectingBank.media, "tw.local.odcRequest.Parties.collectingBank.media");
		mandatory(tw.local.odcRequest.Parties.collectingBank.address, "tw.local.odcRequest.Parties.collectingBank.address");
	}

	/////Parties Types (Accountee)(optional)
	var accounteeCif = tw.local.odcRequest.Parties.partyTypes.partyCIF;
	var accounteeId = tw.local.odcRequest.Parties.partyTypes.partyId;
	if (accounteeCif && accounteeCif.length < 8) {
		addError("tw.local.odcRequest.Parties.partyTypes.partyCIF", "Please enter a Valid CIF or totally remove it", "Please enter a Valid CIF or totally remove it");
	} else if (accounteeCif && !accounteeId) {
		addError("tw.local.odcRequest.Parties.partyTypes.partyCIF", "Please Retrieve CIF Information", "Please Retrieve CIF Information");
	} else if (accounteeCif) {
		if (addIfNotPresent(cifList, accounteeCif) == false) {
			addError("tw.local.odcRequest.Parties.partyTypes.partyCIF", "Please Make sure that each CIF is different for each Party", "Please Make sure that each CIF is different for each Party");
		}

		mandatory(tw.local.odcRequest.Parties.partyTypes.partyId, "tw.local.odcRequest.Parties.partyTypes.partyId");
		mandatory(tw.local.odcRequest.Parties.partyTypes.partyName, "tw.local.odcRequest.Parties.partyTypes.partyName");
		mandatory(tw.local.odcRequest.Parties.partyTypes.country, "tw.local.odcRequest.Parties.partyTypes.country");
		mandatory(tw.local.odcRequest.Parties.partyTypes.language, "tw.local.odcRequest.Parties.partyTypes.language");
		mandatory(tw.local.odcRequest.Parties.partyTypes.refrence, "tw.local.odcRequest.Parties.partyTypes.refrence");
		mandatory(tw.local.odcRequest.Parties.partyTypes.address1, "tw.local.odcRequest.Parties.partyTypes.address1");
	}

	/////Parties Types (Case In Need)(optional)
	var caseInNeedCif = tw.local.odcRequest.Parties.caseInNeed.partyCIF;
	var caseInNeedId = tw.local.odcRequest.Parties.caseInNeed.partyId;

	if (caseInNeedCif && caseInNeedCif.length < 8) {
		addError("tw.local.odcRequest.Parties.caseInNeed.partyCIF", "Please enter a Valid CIF or totally remove it", "Please enter a Valid CIF or totally remove it");
	} else if (caseInNeedCif && !caseInNeedId) {
		addError("tw.local.odcRequest.Parties.caseInNeed.partyCIF", "Please Retrieve CIF Information", "Please Retrieve CIF Information");
	} else if (caseInNeedCif) {
		if (addIfNotPresent(cifList, caseInNeedCif) == false) {
			addError("tw.local.odcRequest.Parties.caseInNeed.partyCIF", "Please Make sure that each CIF is different for each Party", "Please Make sure that each CIF is different for each Party");
		}

		mandatory(tw.local.odcRequest.Parties.caseInNeed.partyId, "tw.local.odcRequest.Parties.caseInNeed.partyId");
		mandatory(tw.local.odcRequest.Parties.caseInNeed.partyName, "tw.local.odcRequest.Parties.caseInNeed.partyName");
		mandatory(tw.local.odcRequest.Parties.caseInNeed.country, "tw.local.odcRequest.Parties.caseInNeed.country");
		mandatory(tw.local.odcRequest.Parties.caseInNeed.language, "tw.local.odcRequest.Parties.caseInNeed.language");
		mandatory(tw.local.odcRequest.Parties.caseInNeed.refrence, "tw.local.odcRequest.Parties.caseInNeed.refrence");
		mandatory(tw.local.odcRequest.Parties.caseInNeed.address1, "tw.local.odcRequest.Parties.caseInNeed.address1");
	}

	validateTab(10, "Parties Tab");

	if (tw.local.odcRequest.complianceApproval == true) mandatory(tw.local.odcRequest.exeHubMkrComment, "tw.local.odcRequest.exeHubMkrComment");
} //end of action

tw.local.errorMessage = "";
/************************************************************************************************************************
/*-------------------------------------------------- Validation Functions ------------------------------------------
************************************************************************************************************************/
/*
 * =========================================================================================================
 *
 * Add a coach validation error
 *
 * EX:	addError(tw.local.name , 'this is a control validation message!' , 'this is a validation message!');
 *
 * =========================================================================================================
 */
function addError(fieldName, controlMessage, validationMessage, fromMandatory) {
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : (tw.local.errorMessage += "<li>" + validationMessage + "</li>");
}
/*
 * =================================================================================================================================
 *
 * Add a coach validation error if the string length is less than given length
 *
 * EX:	minLength(tw.local.name , 'tw.local.name' , 10 , 'this is a control validation message!' , 'this is a validation message!')
 *
 * =================================================================================================================================
 */

function minLength(field, fieldName, len, controlMessage, validationMessage) {
	if (field != null && field != undefined && field.length < len) {
		addError(fieldName, controlMessage, validationMessage);
		return false;
	}
	return true;
}
/*
 * =======================================================================================================================
 *
 * Add a coach validation error if the string length is greater than given length
 *
 * EX:	maxLength(tw.local.name , 'tw.local.name' , 14 , 'this is a validation message!' , 'this is a validation message!')
 *
 * =======================================================================================================================
 */
function maxLength(field, fieldName, len, controlMessage, validationMessage) {
	if (!field) return;
	if (field.length > len) {
		addError(fieldName, controlMessage, validationMessage);
		return false;
	}
	return true;
}

// maxLength(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment", 500, "Shouldn't be more than 500 character", "Comment: " + "Shouldn't be more than 500 character");

/*
 * ==================================================================================================================
 *
 * Add a coach validation error if the field is null 'Mandatory'
 *
 * EX:	notNull(tw.local.name , 'tw.local.name')
 *
 * ==================================================================================================================
 */

function mandatory(field, fieldName) {
	if (field == null || field == undefined) {
		addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
		mandatoryTriggered = true;
		return false;
	} else {
		switch (typeof field) {
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0) {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0) {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
				if (field < 0) {
					var msg = "Invalid Value, This field can not have a negative value.";
					addError(fieldName, msg, msg, true);
					mandatoryTriggered = true;
					return false;
				}
				break;

			default:
				// VALIDATE DATE OBJECT
				if (field && field.getTime && isFinite(field.getTime())) {
				} else {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
		}
	}
	return true;
}
/*
 * ==============================================================================================================================
 *
 * Add a coach validation error if the fromDate bigger than toDate
 *
 * EX:	sumDates(fomDate , toDate , 'tw.local.date' , 'this is a control validation message!' , 'this is a validation message!')
 *
 * =============================================================================================================================
 */

function sumDates(fromDate, toDate, fieldName, controlMessage, validationMessage) {
	if (toDate - fromDate == 0) {
		return true;
	}
	addError(fieldName, controlMessage, validationMessage);
	return false;
}
//=========================================================
//edied b NAIRA
function checkNegativeValue(field, fieldName) {
	//check null values and accep zeroes
	if (field == null || field == undefined) {
		var msg = "Invalid Value, This field can not be empty.";
		addError(fieldName, msg, msg, true);
		mandatoryTriggered = true;
		return false;
	} else {
		if (field < 0) {
			var msg = "Invalid Value, This field can not have a negative value.";
			addError(fieldName, msg, msg, true);
			mandatoryTriggered = true;
			return false;
		}
	}
	return true;
}
//=========================================================
//Validate Decimal(10,6)
function validateDecimal(field, fieldName, controlMessage, validationMessage) {
	// Regular expression pattern for decimal validation
	var decimalPattern = /^\d{1,4}(\.\d{1,6})?$/;

	// Check if the decimal matches the pattern
	if (!decimalPattern.test(field)) {
		// Decimal is valid
		addError(fieldName, controlMessage, controlMessage);
		return false;
	} else {
		// Decimal is invalid
		return true;
	}
}
//========================================================================================
function validateTab(index, tabName) {
	if (tw.system.coachValidation.validationErrors.length > tempLength) {
		if (tw.local.errorMessage.length == 0) {
			tw.local.errorMessage += "<p>" + "Please complete fields in the following tabs:" + "</p>";
		}
		tw.local.errorMessage += "<li>" + tabName + "</li>";
		tempLength = tw.system.coachValidation.validationErrors.length;
		tw.local.invalidTabs[tw.local.invalidTabs.length] = index;
	}
}
//==============================================================
//Validate Decimal(14,2)
function validateDecimal2(field, fieldName, controlMessage, validationMessage) {
	// Regular expression pattern for decimal validation
	var decimalPattern = /^\d{1,12}(\.\d{1,2})?$/;

	// Check if the decimal matches the pattern
	if (!decimalPattern.test(field)) {
		// Decimal is valid
		addError(fieldName, controlMessage, controlMessage);
		return false;
	} else {
		// Decimal is invalid
		return true;
	}
}
//=================================================================================
tw.local.errorMessage != null ? (tw.local.errorPanelVIS = "EDITABLE") : (tw.local.errorPanelVIS = "NONE");

function notPastDate(date, fieldName, controlMessage, validationMessage, exclude) {
	mandatoryTriggered = true;
	if (exclude) {
		if (date != null && date <= new Date()) {
			addError(fieldName, controlMessage, validationMessage, true);
			return false;
		}
		return true;
	} else {
		var today = new Date();

		today.setHours(0, 0, 0, 0);
		if (date != null) date.setHours(0, 0, 0, 0);
		if (date != null && date < today) {
			addError(fieldName, controlMessage, validationMessage, true);
			return false;
		}
		return true;
	}
}
function addIfNotPresent(list, element) {
	if (!list.includes(element)) {
		list.push(element);
		return true;
	} else {
		return false;
	}
}

function notFutureDate(date, fieldName, controlMessage, validationMessage, exclude) {
	if (exclude) {
		if (date != null && date > new Date()) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	} else {
		var today = new Date();
		today.setHours(0, 0, 0, 0);
		if (date != null && date > today) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	}
}

function getMaxDate(dates) {
	if (!Array.isArray(dates) || dates.length === 0) {
		return null; // Return null if input is not an array or is empty
	}

	var maxDate = new Date(dates[0]);
	for (var i = 1; i < dates.length; i++) {
		var currentDate = new Date(dates[i]);
		if (currentDate > maxDate) {
			maxDate = currentDate;
		}
	}
	return maxDate;
}

