************************************************************************************************************************/
//debugger;
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo)
	mandatory(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason");

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.terminateRequest)
	mandatory(tw.local.odcRequest.stepLog.terminateReason, "tw.local.odcRequest.stepLog.terminateReason");

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.createContract || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.amendContract ||
	tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals) {

	////-------------------------------------------------BASIC DETAILS VALIDATION -----------------------------------------
	mandatory(tw.local.odcRequest.BasicDetails.exportPurpose.name, "tw.local.odcRequest.BasicDetails.exportPurpose");
	mandatory(tw.local.odcRequest.BasicDetails.paymentTerms.name, "tw.local.odcRequest.BasicDetails.paymentTerms");
	mandatory(tw.local.odcRequest.BasicDetails.productCategory.name, "tw.local.odcRequest.BasicDetails.productCategory");
	mandatory(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription");
	mandatory(tw.local.odcRequest.BasicDetails.CountryOfOrigin.name, "tw.local.odcRequest.BasicDetails.CountryOfOrigin.value");
	//add mess 160 to local file
	maxLength(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription", 160, "Shouldn't be more than 160 character", "Commodity Description: " + "Shouldn't be more than 160 character");
	if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.createContract || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.recreateContract)
	{
		mandatory(tw.local.odcRequest.BasicDetails.flexCubeContractNo, "tw.local.odcRequest.BasicDetails.flexCubeContractNo");
	}
	if(tw.local.odcRequest.BasicDetails.Invoice.length==0){
	tw.local.errorMessage += "<li>"+"Fill in at least one entry in invoices"+"</li>";	
	tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Invoice", "Fill in at least one entry in invoices");	
	}
	else{
	for(var i=0;i<tw.local.odcRequest.BasicDetails.Invoice.length ; i++){
		mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceDate , "tw.local.odcRequest.BasicDetails.Invoice["+i+"].invoiceDate");
		mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo , "tw.local.odcRequest.BasicDetails.Invoice["+i+"].invoiceNo");
		maxLength(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo , "tw.local.odcRequest.BasicDetails.Invoice["+i+"].invoiceNo", 20 , "Shouldn't be more than 20 character" , "invoice Number: " + "Shouldn't be more than 20 character" );
		}
	} 
	if(tw.local.odcRequest.BasicDetails.Bills.length==0 ){
	tw.local.errorMessage += "<li>"+"Fill in at least one entry in Bills"+"</li>";
	tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Bills", "Fill in at least one entry in Bills");	
	}
	else{
	for(var i=0;i<tw.local.odcRequest.BasicDetails.Bills.length ; i++){	
		mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingDate , "tw.local.odcRequest.BasicDetails.Bills["+i+"].billOfLadingDate");
		mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef , "tw.local.odcRequest.BasicDetails.Bills["+i+"].billOfLadingRef"); 
		maxLength(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef , "tw.local.odcRequest.BasicDetails.Bills["+i+"].billOfLadingRef" , 20 , "Shouldn't be more than 20 character" , "Bill Of lading Ref : " + "Shouldn't be more than 20 character" );
		}
	}	

	maxLength(tw.local.odcRequest.BasicDetails.flexCubeContractNo, "tw.local.odcRequest.BasicDetails.flexCubeContractNo", 16, tw.resource.ValidationMessages.MaxLength16, "Flex Cube Contract Number: " + tw.resource.ValidationMessages.MaxLength16);
	validateTab(0, "Basic Details Tab");
	//-------------------------------------------------DOCUMENT GENERATION INFO VALIDATION -----------------------------------------	
	if (tw.local.odcRequest.requestNature.value == tw.epv.RequestNature.NewRequest) {
		mandatory(tw.local.odcRequest.GeneratedDocumentInfo.customerName, "tw.local.odcRequest.GeneratedDocumentInfo.customerName");
		mandatory(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress, "tw.local.odcRequest.GeneratedDocumentInfo.customerAddress");
		if (tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value, "tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption");
		}


		if (tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length == 0) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[0], "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra");
			tw.local.errorMessage += "<li>" + "Fill in at least one entry in delivery terms Extra" + "</li>";
		}
		else {
			for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length; i++) {
				mandatory(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[" + i + "]");
			}
		}
		if (tw.local.odcRequest.GeneratedDocumentInfo.Instructions.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.length == 0) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[0], "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra");
			tw.local.errorMessage += "<li>" + "Fill in at least one entry in instructions Extra" + "</li>";
		}
		if (tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.length == 0) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[0], "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra");
			tw.local.errorMessage += "<li>" + "Fill in at least one entry in payment Instructions Extra" + "</li>";
		}
		if (tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.length == 0) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[0], "tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra");
			tw.local.errorMessage += "<li>" + "Fill in at least one entry in special instructions Extra" + "</li>";
		}

		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[" + i + "]");
		}
		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[" + i + "]");
		}
		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[" + i + "]");
		}
		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[" + i + "]");
		}
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.customerName, "tw.local.odcRequest.GeneratedDocumentInfo.customerName", 250, "Shouldn't be more than 250 character", "customer Name: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress, "tw.local.odcRequest.GeneratedDocumentInfo.customerAddress", 400, "Shouldn't be more than 400 character", "customer Address: " + "Shouldn't be more than 400 character");

		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra", 250, "Shouldn't be more than 250 character", "Delivery Terms Extra: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra", 250, "Shouldn't be more than 250 character", "Instructions Extra: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra", 250, "Shouldn't be more than 250 character", "payment Instructions Extra: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra", 250, "Shouldn't be more than 250 character", "Special Instructions Extra: " + "Shouldn't be more than 250 character");

		if (tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetter == true) {
			if (tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.name == "003") {
				maxLength(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle, "tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle", 80, "Shouldn't be more than 80 character", "Regenerate RemLetter Title: " + "Shouldn't be more than 80 character");
			}
		}
		validateTab(1, "Letter Generation Tab");
		//maxLength(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle , "tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle", 80 , "Shouldn't be more than 80 character" , "Regenerate RemLetter Title: " + "Shouldn't be more than 80 character" );
	}
	//-----------------------------------------------FINANCIAL DETAILS - BRANCH VALIDATION -------------------------------------	
	mandatory(tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate, "tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate");
	notPastDate(tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate, 'tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate', 'cannot select date in the past', 'cannot select date in the past', true);
	//mandatory(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced , "tw.local.odcRequest.FinancialDetailsBR.amountAdvanced");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced, "tw.local.odcRequest.FinancialDetailsBR.amountAdvanced");
	minLength(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced, "tw.local.odcRequest.FinancialDetailsBR.amountAdvanced", 2, "Shouldn't be less than 14 character", "Amount Advanced: Shouldn't be less than 2 character");
	maxLength(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced, "tw.local.odcRequest.FinancialDetailsBR.amountAdvanced", 14, "Shouldn't be more than 14 character", "Amount Advanced:" + "Shouldn't be more than 14 character");

	if(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced > 0.0)
	{
		mandatory(tw.local.odcRequest.FinancialDetailsBR.chargesAndCommissionsAccount.value , "tw.local.odcRequest.FinancialDetailsBR.chargesAndCommissionsAccount");
		mandatory(tw.local.odcRequest.FinancialDetailsBR.collectionAccount.value , "tw.local.odcRequest.FinancialDetailsBR.collectionAccount");
	}

	validateTab(3, "Financial Details - Branch Tab");
	//-----------------------------------------------FLEX CUBE COLLECTIONS VALIDATION -------------------------------------	
//This change according to mosallam meeting 12-11-2023
//mandatory(tw.local.odcRequest.FcCollections.currency.name , "tw.local.odcRequest.FcCollections.currency");
//mandatory(tw.local.odcRequest.FcCollections.negotiatedExchangeRate , "tw.local.odcRequest.FcCollections.negotiatedExchangeRate");
//mandatory(tw.local.odcRequest.FcCollections.fromDate , "tw.local.odcRequest.FcCollections.fromDate");
//mandatory(tw.local.odcRequest.FcCollections.ToDate , "tw.local.odcRequest.FcCollections.ToDate");
//mandatory(tw.local.odcRequest.FcCollections.accountNo.value , "tw.local.odcRequest.FcCollections.accountNo");
//sumDates(tw.local.odcRequest.FcCollections.fromDate, tw.local.odcRequest.FcCollections.ToDate , "tw.local.odcRequest.FcCollections.ToDate" ,"Search Transactions To Date must be bigger than Search Transactions From Date" , "Search Transactions To Date must be bigger than Search Transactions From Date" );
if(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced > 0.0)
{
	mandatory(tw.local.odcRequest.FcCollections.totalAllocatedAmount , "tw.local.odcRequest.FcCollections.totalAllocatedAmount");
if(tw.local.confirmBool == false)
{
	if(tw.local.odcRequest.FcCollections!= null && (tw.local.odcRequest.FcCollections.totalAllocatedAmount != 0 && tw.local.odcRequest.FcCollections.totalAllocatedAmount != tw.local.odcRequest.FinancialDetailsBR.amountAdvanced))
	{
		tw.local.confirmBool = confirm("Total allocated amount should be equal to the advance amount");
	}
}

if(tw.local.odcRequest.FcCollections != null && tw.local.odcRequest.FcCollections.negotiatedExchangeRate != null)
{
	minLength(tw.local.odcRequest.FcCollections.negotiatedExchangeRate,"tw.local.odcRequest.FcCollections.negotiatedExchangeRate", 6 ,"Shouldn't be less than 6 character"," Negotiated Exchange Rate: Shouldn't be less than 6 character");
	maxLength(tw.local.odcRequest.FcCollections.negotiatedExchangeRate , "tw.local.odcRequest.FcCollections.negotiatedExchangeRate", 10 , "Shouldn't be more than 10 character" , " Negotiated Exchange Rate:" + "Shouldn't be more than 10 character" );
}
}
if(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced == 0.0 && tw.local.odcRequest.FcCollections.selectedTransactions.length >0)
{
	tw.local.errorMessage += "<li>"+"No Transactions should be retrieved advanced amount equals zero"+"</li>";	
	tw.system.coachValidation.addValidationError("tw.local.odcRequest.FcCollections.retrievedTransactions", "Mandatory Field can't left blank");
	
}
if(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced > 0.0)
{
	
	for(var i=0; i<tw.local.odcRequest.FcCollections.selectedTransactions.length;i++)
	{
	 var totalTransAmount = tw.local.odcRequest.FcCollections.selectedTransactions[i].existAmount + tw.local.odcRequest.FcCollections.selectedTransactions[i].amountAllocatedForCurrencyRequest;
	
	 if(tw.local.odcRequest.FcCollections.selectedTransactions[i].transactionAmount < totalTransAmount)
	 {
	 		tw.local.errorMessage += "<li>"+"Amount Allocated for currenct request and amount linked in bpm shoudn't be greater than transaction amount"+"</li>";	
	 		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FcCollections.selectedTransactions["+i+"].amountAllocatedForCurrencyRequest", "Amount Allocated for currenct request and amount linked in bpm shoudn't be greater than transaction amount");
	 		
	 }
	 
	}
if(tw.local.odcRequest.FcCollections.fromDate !=null && tw.local.odcRequest.FcCollections.ToDate !=null)
{
	if(tw.local.odcRequest.FcCollections.fromDate >= tw.local.odcRequest.FcCollections.ToDate)
	{
		tw.local.errorMessage += "<li>"+" Search Transactions From Date shouln't be greater than Search Transactions To Date"+"</li>";	
		 tw.system.coachValidation.addValidationError("tw.local.odcRequest.FcCollections.fromDate", "Search Transactions From Date shouln't be greater than Search Transactions To Date");
		 tw.system.coachValidation.addValidationError("tw.local.odcRequest.FcCollections.ToDate", "Search Transactions From Date shouln't be greater than Search Transactions To Date");
	}
}	
if(tw.local.odcRequest.FcCollections.selectedTransactions.length !=0)
{
 for (var i = 0; i < tw.local.odcRequest.FcCollections.selectedTransactions.length; i++) 
 {
 for (var j = 0; j < tw.local.odcRequest.FcCollections.selectedTransactions.length; j++) 
 {
 if (i != j) 
 {
 if (tw.local.odcRequest.FcCollections.selectedTransactions[i].referenceNumber == tw.local.odcRequest.FcCollections.selectedTransactions[j].referenceNumber) 
 {
// alert("This Tranaction Reference Number have been added before");
 tw.system.coachValidation.addValidationError("tw.local.odcRequest.FcCollections.selectedTransactions["+i+"].referenceNumber", "This Tranaction Reference Number have been added before");
 
 }
 
 
 }
 
 }
 }
			 

}
}

		validateTab(4, "Flexcube collections Tab");
	
	//-----------------------------------------Financial Details - Trade FO VALIDATION ---------------------------------
	mandatory(tw.local.odcRequest.FinancialDetailsFO.discount, "tw.local.odcRequest.FinancialDetailsFO.discount");
	mandatory(tw.local.odcRequest.FinancialDetailsFO.ourCharges, "tw.local.odcRequest.FinancialDetailsFO.ourCharges");
	mandatory(tw.local.odcRequest.FinancialDetailsFO.amountSight, "tw.local.odcRequest.FinancialDetailsFO.amountSight");
	mandatory(tw.local.odcRequest.FinancialDetailsFO.extraCharges, "tw.local.odcRequest.FinancialDetailsFO.extraCharges");

	mandatory(tw.local.odcRequest.FinancialDetailsFO.maturityDate, "tw.local.odcRequest.FinancialDetailsFO.maturityDate");
	mandatory(tw.local.odcRequest.FinancialDetailsFO.noOfDaysMaturity, "tw.local.odcRequest.FinancialDetailsFO.noOfDaysMaturity");
	mandatory(tw.local.odcRequest.FinancialDetailsFO.financeApprovalNo, "tw.local.odcRequest.FinancialDetailsFO.financeApprovalNo");
//	mandatory(tw.local.odcRequest.FinancialDetailsFO.executionHub.name, "tw.local.odcRequest.FinancialDetailsFO.executionHub");

	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.discount, "tw.local.odcRequest.FinancialDetailsFO.discount");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.extraCharges, "tw.local.odcRequest.FinancialDetailsFO.extraCharges");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.ourCharges, "tw.local.odcRequest.FinancialDetailsFO.ourCharges");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.amountSight, "tw.local.odcRequest.FinancialDetailsFO.amountSight");

	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.collectableAmount, "tw.local.odcRequest.FinancialDetailsFO.collectableAmount");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization, "tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization, "tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization");

	if (tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization > 0 && tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization > 0) {
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization", "Partial Avalization isn't allowed");
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization", "Partial Avalization isn't allowed");
	}
	var sumAvalization = parseFloat(0);
	sumAvalization = tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization + tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization + tw.local.odcRequest.FinancialDetailsFO.amountSight;
	if (sumAvalization != tw.local.odcRequest.FinancialDetailsFO.collectableAmount) {
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization", "please ensure that the following fields is equal to Amount Collectable by NBE:Amount Sight,Amount Deferred - No Avalization,Amount Deferred - Avalization");
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization", "please ensure that the following fields is equal to Amount Collectable by NBE:Amount Sight,Amount Deferred - No Avalization,Amount Deferred - Avalization");
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountSight", "please ensure that the following fields is equal to Amount Collectable by NBE:Amount Sight,Amount Deferred - No Avalization,Amount Deferred - Avalization");
	}


	//-------------------------MultiTenor Dates---------------------------------------------


	if (tw.local.odcRequest.BasicDetails.paymentTerms.name != "001")//not equal sight
	{
		if (tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.length == 0) {
			mandatory(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates, "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates");
			tw.local.errorMessage += "<li>" + "Fill in at least one entry in Multi Tenordates" + "</li>";
		}

		var sum = 0;

		for (var i = 0; i < tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.length; i++) {
			if (tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount == "" || tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount == null) {

				tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].amount", "Mandatory field");
			}
			else if (tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount != "") {
				checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount, "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].amount");
			}
			if (tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].date == "" || tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].date == null) {
				tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].date", "Mandatory field");
			}


			notPastDate(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].date, "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].date", 'cannot select date in the past', 'cannot select date in the past', true);

			sum = sum + tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount;
		}

		//if(!!tw.local.odcRequest.FinancialDetailsFO.collectableAmount && tw.local.odcRequest.FinancialDetailsFO.collectableAmount <0 )

		if (tw.local.odcRequest.FinancialDetailsFO.collectableAmount != null && tw.local.odcRequest.FinancialDetailsFO.collectableAmount < sum) {
			tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.collectableAmount", "Sum of all Installment Amounts in a request must be <= Amount Collectable by NBE (اجمالى المبالغ المطلوب تحصيلها)");
			tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.length -1 ].date", "Mandatory field");
		}
