ns16:extensionElements.ns2:postAssignmentScript:
var action = tw.local.odcRequest.stepLog.action;
if(action != tw.epv.CreationActions.obtainApprovals  && tw.local.odcRequest.complianceApproval == true)
{
	tw.local.odcRequest.complianceApproval = false;
}

if (action == tw.epv.CreationActions.createContract || action == tw.epv.CreationActions.amendContract || 
	action == tw.epv.CreationActions.recreateContract || action == tw.epv.CreationActions.obtainApprovals)
		tw.local.needValid = true;
		
if (action == tw.epv.CreationActions.createContract || action == tw.epv.CreationActions.amendContract || 
	action == tw.epv.CreationActions.recreateContract)
		tw.local.needInteg = true;

ns16:extensionElements.ns2:preAssignmentScript:
tw.local.requestTypeRecreate = "" + tw.epv.RequestType.Recreate;
tw.local.deliveryterms = tw.epv.TermsAndConditions.deliveryTerms;
tw.local.paymentTerms = tw.epv.TermsAndConditions.paymentTerms;
tw.local.specialInstructions = tw.epv.TermsAndConditions.specialInstructions;
tw.local.instructions = tw.epv.TermsAndConditions.instructions;
tw.local.activityName = "ACT04";
tw.local.requestCreate = "" + tw.epv.RequestType.Create;
tw.local.requestAmend = tw.epv.RequestType.Amendment+"";
tw.local.calculateOutstandingAmount = true;
if( tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create ){
  tw.local.calculateOutstandingAmount = false;
  
}

tw.local.positionSearch = false;
tw.local.disable = false;

ns16:scriptTask.ns16:script:
//Initializing customer and party account list
tw.local.odcRequest.customerAndPartyAccountList = [];
tw.local.todayDate = new Date();
var todayDate = new Date();
tw.local.odcRequest.ContractCreation.valueDate = todayDate;
tw.local.futureDate = new Date(todayDate);
tw.local.futureDate.setDate(tw.local.todayDate.getDate() +2 );
tw.local.odcRequest.stepLog={};
tw.local.odcRequest.stepLog.startTime =new Date();
tw.local.odcRequest.stepLog.step = ""+tw.epv.ScreenNames.CACT04;

tw.local.odcRequest.appInfo.stepName =""+tw.epv.ScreenNames.CACT04;

tw.local.actionConditions = {};

tw.local.actionConditions.complianceApproval= tw.local.odcRequest.complianceApproval;
tw.local.actionConditions.screenName= tw.epv.ScreenNames.CACT04;
tw.local.actionConditions.userRole= tw.local.odcRequest.initiator;
//tw.local.actionConditions.lastStepAction= tw.epv.ScreenNames.CACT03;
tw.local.actionConditions.requestType = tw.local.odcRequest.requestType.value;

tw.local.deliveryterms = tw.epv.TermsAndConditions.deliveryTerms;
tw.local.paymentTerms = tw.epv.TermsAndConditions.paymentTerms;
tw.local.specialInstructions = tw.epv.TermsAndConditions.specialInstructions;
tw.local.instructions = tw.epv.TermsAndConditions.instructions;
//////////////////////initializing parties drawer section

///// Initializing Drawee Section in parties cv
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create){
    tw.local.odcRequest.Parties.Drawer ={};
    tw.local.odcRequest.Parties.Drawer.partyId = tw.local.odcRequest.cif;
    tw.local.odcRequest.Parties.Drawer.partyName = tw.local.odcRequest.GeneratedDocumentInfo.customerName;
    tw.local.odcRequest.Parties.Drawer.Language= "ENG";
    tw.local.odcRequest.Parties.Drawer.country = "EG"
    tw.local.odcRequest.Parties.Drawer.Reference = "NO REF";
    tw.local.odcRequest.Parties.Drawer.address1 = tw.local.odcRequest.GeneratedDocumentInfo.customerAddress.slice(0,35);
    tw.local.odcRequest.Parties.Drawer.address2 = tw.local.odcRequest.GeneratedDocumentInfo.customerAddress.slice(35,70);
    tw.local.odcRequest.Parties.Drawer.address3 = tw.local.odcRequest.GeneratedDocumentInfo.customerAddress.slice(70,200);

	tw.local.odcRequest.Parties.Drawee ={};
	tw.local.odcRequest.Parties.Drawee.partyId ="";
	tw.local.odcRequest.Parties.Drawee.partyName = tw.local.odcRequest.ImporterDetails.importerName;
	tw.local.odcRequest.Parties.Drawee.Language= "ENG";
	tw.local.odcRequest.Parties.Drawee.country = tw.local.odcRequest.ImporterDetails.importerCountry.value;
	tw.local.odcRequest.Parties.Drawee.Reference = "NO REF";
	tw.local.odcRequest.Parties.Drawee.address1 = tw.local.odcRequest.ImporterDetails.importerAddress.slice(0,35);
	tw.local.odcRequest.Parties.Drawee.address2 = tw.local.odcRequest.ImporterDetails.importerAddress.slice(35,70);
	tw.local.odcRequest.Parties.Drawee.address3 = tw.local.odcRequest.ImporterDetails.importerAddress.slice(70,200);
	
	////initializing Collecting bank ref section in parties cv
	tw.local.odcRequest.Parties.collectingBank = {};
	tw.local.odcRequest.Parties.collectingBank.reference = tw.local.odcRequest.FinancialDetailsFO.referenceNo;
	
	///// Initializing partyTypes Section in parties cv
	tw.local.odcRequest.Parties.caseInNeed = {};
	tw.local.odcRequest.Parties.partyTypes = {};

    //setting value of source reference to bpm request number
 //   tw.local.odcRequest.ContractCreation.sourceReference = "";
    //tw.local.odcRequest.ContractCreation.sourceReference = tw.local.odcRequest.requestNo;
    tw.local.odcRequest.ContractCreation.currency = tw.local.odcRequest.FinancialDetailsBR.currency.name;
    tw.local.odcRequest.ContractCreation.amount = tw.local.odcRequest.FinancialDetailsFO.collectableAmount;
}

/*Visibilty Conditions*/
/*Basic Details CV Visibility*/
///////////////////////////////
if(tw.local.odcRequest.requestNature.value == tw.epv.RequestNature.UpdateRequest)
	tw.local.parentRequestNumberVIS = "READONLY";
	
else
	tw.local.parentRequestNumberVIS = "None";
	
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create ||tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Recreate  || tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Amendment){
	tw.local.contractStageVIS = "READONLY";
}
else{
tw.local.contractStageVIS = "NONE";
}
/*Document Generation Section*/
///////////////////////////////
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate){
	tw.local.requestTypeVIS = "EDITABLE";
}
else{
	tw.local.requestTypeVIS = "NONE";	
}
/*Importer Details Visibility*/
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate){
	tw.local.bankRefVIS = "EDITABLE";
}
else{
	tw.local.bankRefVIS = "NONE";	
}
////////////////////////////////////////////////////////

////////////////////////////////////////////////////////////////
/*Add remaining conditions based on the request type*/
if(tw.local.odcRequest.BasicDetails.contractStage == "Final" || tw.local.odcRequest.BasicDetails.contractStage == "FIN")
{
	tw.local.event = "INIT";
}

tw.local.initialAccountList = {};
tw.local.initialAccountList = tw.local.odcRequest.FcCollections.listOfAccounts;

tw.local.errorPanelVIS="NONE";
tw.local.odcRequest.ContractCreation.baseDate = new Date();
//=====================
if(tw.local.lastAction == tw.epv.CreationActions.submitRequestToHubDirectly)
{
	tw.local.executionSectionVIS = "None";
	
}
else
{
	tw.local.executionSectionVIS = "Readonly";
	
}

if(tw.local.odcRequest.stepLog.action      == tw.epv.CreationActions.obtainApprovals){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InExecution;
	tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.pendingExecutionHubInitiationReview;
	tw.local.lastAction = tw.epv.CreationActions.obtainApprovals;
	tw.local.odcRequest.actions = [];
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.createContract){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InExecution
	tw.local.odcRequest.appInfo.subStatus = ""+ tw.epv.Status.pendingExecutionHubInitiationReview;
	tw.local.lastAction = "";
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.amendContract){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InExecution
	tw.local.odcRequest.appInfo.subStatus = ""+ tw.epv.Status.pendingExecutionHubInitiationReview;
	tw.local.lastAction = "";
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.recreateContract){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InExecution
	tw.local.odcRequest.appInfo.subStatus = ""+ tw.epv.Status.pendingExecutionHubInitiationReview;
	tw.local.lastAction = "";
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InApproval;
	tw.local.odcRequest.appInfo.subStatus = ""+ tw.epv.Status.pendingExecutionHubInitiationReview;
	tw.local.lastAction = tw.epv.CreationActions.returnToTradeFo;
	tw.local.odcRequest.actions = [];
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.terminateRequest){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InApproval;
	tw.local.odcRequest.appInfo.subStatus = ""+ tw.epv.Status.pendingExecutionHubInitiationReview;
	tw.local.lastAction = tw.epv.CreationActions.terminateRequest;
	tw.local.odcRequest.actions = [];
	
}

tw.local.compApprovalInit = "EXE";
////setting value of contract creation date
tw.local.contractCreationDate = tw.local.odcRequest.ContractCreation.baseDate;

tw.local.errorMessage = "";
var mandatoryTriggered = false;
var tempLength = 0;
//var matDates = [];
tw.local.invalidTabs = [];
tw.system.coachValidation.clearValidationErrors();
var validateDec14 = "accepts 14 digits before the decimal point and 2 digits after it.";
//tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.recreateContract
/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//debugger;
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");
if (tw.local.odcRequest.stepLog.comment != null && tw.local.odcRequest.stepLog.comment != "") {
	maxLength(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment", 500, "Shouldn't be more than 500 character", " Comment :" + "Shouldn't be more than 500 character");
}

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals && tw.local.odcRequest.complianceApproval == false) {
	tw.local.odcRequest.stepLog.action = "";
	tw.system.coachValidation.addValidationError("tw.local.odcRequest.stepLog.action", tw.resource.ValidationMessages.MandatoryFields);
}

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals) mandatory(tw.local.odcRequest.exeHubMkrComment, "tw.local.odcRequest.exeHubMkrComment");

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo) {
	mandatory(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason", 80, "Shouldn't be more than 80 characters", "Return reason :- This field shouldn't be more than 80 character");
}
if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.terminateRequest) {
	mandatory(tw.local.odcRequest.stepLog.terminateReason, "tw.local.odcRequest.stepLog.terminateReason");
	maxLength(tw.local.odcRequest.stepLog.terminateReason, "tw.local.odcRequest.stepLog.terminateReason", 80, "Shouldn't be more than 80 characters", "Termination reason :- This field shouldn't be more than 80 character");
}
if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.createContract || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.amendContract || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.recreateContract || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals) {
	//-------------------------------------------------Attachment----------------------------
	if (tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create) {
		var selectedAttached = tw.local.odcRequest.attachmentDetails.attachment.listAllSelectedIndices;
		if (selectedAttached.length == 0 || selectedAttached.includes(0) == false) {
			addError("tw.local.odcRequest.attachmentDetails.attachment[0].name", "Customer Request is mandatory to be checked");
		}
	}

	////-------------------------------------------------BASIC DETAILS VALIDATION -----------------------------------------
	mandatory(tw.local.odcRequest.BasicDetails.exportPurpose.name, "tw.local.odcRequest.BasicDetails.exportPurpose");
	mandatory(tw.local.odcRequest.BasicDetails.paymentTerms.name, "tw.local.odcRequest.BasicDetails.paymentTerms");
	mandatory(tw.local.odcRequest.BasicDetails.productCategory.name, "tw.local.odcRequest.BasicDetails.productCategory");
	mandatory(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription");
	mandatory(tw.local.odcRequest.BasicDetails.CountryOfOrigin.name, "tw.local.odcRequest.BasicDetails.CountryOfOrigin.value");
	//add mess 160 to local file
	maxLength(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription", 160, "Shouldn't be more than 160 character", "Commodity Description: " + "Shouldn't be more than 160 character");

	if (tw.local.odcRequest.BasicDetails.Invoice.length == 0) {
		//		tw.local.errorMessage += "<li>" + "Fill in at least one entry in invoices" + "</li>";
		tw.system.coachValidation.addValidationError("tw.local.invoiceBillExist", "Fill in at least one entry in invoices");
	} else {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Invoice.length; i++) {
			mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceDate, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceDate");
			mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceNo");
			maxLength(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceNo", 20, "Shouldn't be more than 20 character", "invoice Number: " + "Shouldn't be more than 20 character");
		}
	}
	tw.local.invoiceBillExist;
	if (tw.local.odcRequest.BasicDetails.Bills.length == 0) {
		//		tw.local.errorMessage += "<li>" + "Fill in at least one entry in Bills" + "</li>";
		tw.system.coachValidation.addValidationError("tw.local.invoiceBillExist", "Fill in at least one entry in Bills");
	} else {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Bills.length; i++) {
			mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingDate, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingDate");
			mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingRef");
			maxLength(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingRef", 20, "Shouldn't be more than 20 character", "Bill Of lading Ref : " + "Shouldn't be more than 20 character");
		}
	}

	if (tw.local.billsExist == true) {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Bills.length; i++) {
			tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Bills", "This Bills Number already exist before for the same CIF number");
		}
	}
	if (tw.local.InvoiceExist == true) {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Invoice.length; i++) {
			tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Invoice", "This Invoive Number already exist before for the same CIF number");
		}
	}
	validateTab(0, "Basic Details Tab");

	//-------------------------------------------------DOCUMENT GENERATION INFO VALIDATION -----------------------------------------
	var needRegenerate = (tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate) && tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetter == true;

	var newRequest = tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create;

	if (needRegenerate) {
		mandatory(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value, "tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption");
	}

	if (needRegenerate || newRequest) {
		mandatory(tw.local.odcRequest.GeneratedDocumentInfo.customerName, "tw.local.odcRequest.GeneratedDocumentInfo.customerName");
		mandatory(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress, "tw.local.odcRequest.GeneratedDocumentInfo.customerAddress");

		if (tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length == 0) {
			addError("tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms[" + 0 + "]", "Fill in at least one entry in delivery terms or delivery terms extra");
		} else {
			for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length; i++) {
				mandatory(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[" + i + "]");
			}
		}
		if (tw.local.odcRequest.GeneratedDocumentInfo.Instructions.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.length == 0) {
			addError("tw.local.odcRequest.GeneratedDocumentInfo.Instructions[" + 0 + "].value", "Fill in at least one entry in instructions or instructions extra");
		}
		if (tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.length == 0) {
			addError("tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions[" + 0 + "].value", "Fill in at least one entry in payment Instructions or payment instructions extra");
		}
		if (tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.length == 0) {
			addError("tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions[" + 0 + "].value", "Fill in at least one entry in special instructions or special instructions extra");
		}

		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[" + i + "]");
		}
		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[" + i + "]");
		}
		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[" + i + "]");
		}
		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[" + i + "]");
		}
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.customerName, "tw.local.odcRequest.GeneratedDocumentInfo.customerName", 250, "Shouldn't be more than 250 character", "customer Name: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress, "tw.local.odcRequest.GeneratedDocumentInfo.customerAddress", 400, "Shouldn't be more than 400 character", "customer Address: " + "Shouldn't be more than 400 character");

		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra", 250, "Shouldn't be more than 250 character", "Delivery Terms Extra: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra", 250, "Shouldn't be more than 250 character", "Instructions Extra: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra", 250, "Shouldn't be more than 250 character", "payment Instructions Extra: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra", 250, "Shouldn't be more than 250 character", "Special Instructions Extra: " + "Shouldn't be more than 250 character");

		if (tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetter == true) {
			if (tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.name == "003") {
				maxLength(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle, "tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle", 80, "Shouldn't be more than 80 character", "Regenerate RemLetter Title: " + "Shouldn't be more than 80 character");
			}
		}
	}

	//-----------------------------------------------FINANCIAL DETAILS - BRANCH VALIDATION -------------------------------------
	mandatory(tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate, "tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate");
	notPastDate(tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate, "tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate", "cannot select date in the past", "cannot select date in the past", true);

	checkNegativeValue(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced, "tw.local.odcRequest.FinancialDetailsBR.amountAdvanced");

	if (tw.local.odcRequest.FinancialDetailsBR.amountAdvanced > 0) {
		mandatory(tw.local.odcRequest.FinancialDetailsBR.chargesAndCommissionsAccount, "tw.local.odcRequest.FinancialDetailsBR.chargesAndCommissionsAccount");
		mandatory(tw.local.odcRequest.FinancialDetailsBR.collectionAccount, "tw.local.odcRequest.FinancialDetailsBR.collectionAccount");
	}
	if (tw.local.odcRequest.FinancialDetailsBR.amountAdvanced > tw.local.odcRequest.FinancialDetailsBR.documentAmount) {
		mandatory(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced, "tw.local.odcRequest.FinancialDetailsBR.amountAdvanced");
		addError("tw.local.odcRequest.FinancialDetailsBR.amountAdvanced", "Amount Advanced must be less than or equal document amount");
	}
	validateTab(3, "Financial Details - Branch Tab");
	//-----------------------------------------------FLEX CUBE COLLECTIONS VALIDATION -------------------------------------
	//This change according to mosallam meeting 12-11-2023
	//mandatory(tw.local.odcRequest.FcCollections.currency.name , "tw.local.odcRequest.FcCollections.currency");
	//mandatory(tw.local.odcRequest.FcCollections.negotiatedExchangeRate , "tw.local.odcRequest.FcCollections.negotiatedExchangeRate");
	//mandatory(tw.local.odcRequest.FcCollections.fromDate , "tw.local.odcRequest.FcCollections.fromDate");
	//mandatory(tw.local.odcRequest.FcCollections.ToDate , "tw.local.odcRequest.FcCollections.ToDate");
	//mandatory(tw.local.odcRequest.FcCollections.accountNo.value , "tw.local.odcRequest.FcCollections.accountNo");
	//sumDates(tw.local.odcRequest.FcCollections.fromDate, tw.local.odcRequest.FcCollections.ToDate , "tw.local.odcRequest.FcCollections.ToDate" ,"Search Transactions To Date must be bigger than Search Transactions From Date" , "Search Transactions To Date must be bigger than Search Transactions From Date" );
	if (tw.local.odcRequest.FinancialDetailsBR.amountAdvanced > 0.0) {
		mandatory(tw.local.odcRequest.FcCollections.totalAllocatedAmount, "tw.local.odcRequest.FcCollections.totalAllocatedAmount");
		if (tw.local.odcRequest.FcCollections.currency.value != null) {
			mandatory(tw.local.odcRequest.FcCollections.negotiatedExchangeRate, "tw.local.odcRequest.FcCollections.negotiatedExchangeRate");
		}
		if (tw.local.confirmBool == false) {
			if (tw.local.odcRequest.FcCollections != null && tw.local.odcRequest.FcCollections.totalAllocatedAmount != 0 && tw.local.odcRequest.FcCollections.totalAllocatedAmount != tw.local.odcRequest.FinancialDetailsBR.amountAdvanced) {
				var userResponse = confirm("In Financial Details Tab - Total allocated amount should be equal to the advance amount");

				if (!userResponse) {
					tw.system.coachValidation.addValidationError("", "");
				} else {
					tw.local.confirmBool = true;
				}
			}
		}
		if (tw.local.odcRequest.FcCollections != null && tw.local.odcRequest.FcCollections.negotiatedExchangeRate != null) {
			//minLength(tw.local.odcRequest.FcCollections.negotiatedExchangeRate,"tw.local.odcRequest.FcCollections.negotiatedExchangeRate", 6 ,"Shouldn't be less than 6 character"," Negotiated Exchange Rate: Shouldn't be less than 6 character");
			//	maxLength(tw.local.odcRequest.FcCollections.negotiatedExchangeRate , "tw.local.odcRequest.FcCollections.negotiatedExchangeRate", 10 , "Shouldn't be more than 10 character" , " Negotiated Exchange Rate:" + "Shouldn't be more than 10 character" );
