			if (tw.local.odcRequest.ChargesAndCommissions[i].changeAmount < 0 || tw.local.odcRequest.ChargesAndCommissions[i].changeAmount == null) {
				addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].changeAmount", "Change Amount Must be >= 0", "Change Amount Must be >= 0");
			} else if (tw.local.odcRequest.ChargesAndCommissions[i].changeAmount > 0) {
				validateDecimal2(tw.local.odcRequest.ChargesAndCommissions[i].changeAmount, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].changeAmount", "Change Amount Must be Decimal(14,2)")
			}

			//Fixed Rate
		} else {

			if (tw.local.odcRequest.ChargesAndCommissions[i].changePercentage < 0 || tw.local.odcRequest.ChargesAndCommissions[i].changePercentage == null) {
				addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].changePercentage", "Change Percentage Must be >= 0", "Change Percentage Must be >= 0");
